import { useState, useEffect } from 'react';
import { hrGetForms, hrCreateForm, hrUpdateForm, hrDeleteForm, hrActivateForm, hrDeactivateForm, hrAddQuestion, hrDeleteQuestion } from '../../api/index.js';
import { Spinner, Modal, Input, Textarea, Btn, Badge, useToast } from '../../components/shared/index.jsx';

const FIELD_TYPES = ['score_1_4', 'boolean', 'decimal'];
const FIELD_LABELS = { score_1_4: 'Score 1-4', boolean: 'Yes / No', decimal: 'Decimal' };

export function HRFormsPage() {
  const toast = useToast();
  const [forms, setForms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedForm, setSelected] = useState(null);
  const [showCreate, setShowCreate] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [showAddQ, setShowAddQ] = useState(false);
  const [formData, setFormData] = useState({ title: '', description: '' });
  const [qData, setQData] = useState({ questionText: '', fieldType: 'score_1_4', order: 0 });
  const [saving, setSaving] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const data = await hrGetForms();
      const formsArray = Array.isArray(data) ? data : [];
      setForms(formsArray);

      // If a form was already selected, refresh its data from the new list
      if (selectedForm) {
        const updatedSelected = formsArray.find(f => f.formID === selectedForm.formID);
        if (updatedSelected) setSelected(updatedSelected);
      }
    } catch { 
      toast('Failed to load forms', 'error'); 
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const handleSelectForm = (form) => {
    // Ensuring we set the form from the state which should contain the questions
    setSelected(form);
  };

  const handleCreate = async () => {
    if (!formData.title.trim()) { toast('Title is required', 'error'); return; }
    setSaving(true);
    try {
      const res = await hrCreateForm(formData);
      if (res.formID) { 
        toast('Form created'); 
        setShowCreate(false); 
        setFormData({ title: '', description: '' }); 
        await load(); 
      }
    } catch { toast('Failed to create form', 'error'); }
    setSaving(false);
  };

  const handleUpdate = async () => {
    if (!formData.title.trim()) { toast('Title is required', 'error'); return; }
    setSaving(true);
    try {
      const res = await hrUpdateForm(selectedForm.formID, formData);
      if (res.formID) { 
        toast('Form updated'); 
        setShowEdit(false); 
        await load(); 
      }
    } catch { toast('Failed to update form', 'error'); }
    setSaving(false);
  };

  const handleDelete = async (form) => {
    if (!window.confirm(`Delete "${form.title}"?`)) return;
    try {
      await hrDeleteForm(form.formID);
      toast('Form deleted');
      if (selectedForm?.formID === form.formID) setSelected(null);
      load();
    } catch { toast('Delete failed', 'error'); }
  };

  const handleToggleActive = async (form) => {
    try {
      if (form.isActive) await hrDeactivateForm(form.formID);
      else await hrActivateForm(form.formID);
      toast(`Form status updated`);
      load();
    } catch { toast('Status toggle failed', 'error'); }
  };

  const handleAddQuestion = async () => {
    if (!qData.questionText) return toast('Question text is required', 'error');
    setSaving(true);
    try {
      const payload = {
        questionText: qData.questionText,
        fieldType: qData.fieldType,
        order: parseInt(qData.order) || 0
      };
      await hrAddQuestion(selectedForm.formID, payload);
      toast('Question added successfully');
      setShowAddQ(false); 
      setQData({ questionText: '', fieldType: 'score_1_4', order: 0 });

      // Crucial: Reload all forms to get the updated nested questions array
      await load(); 
    } catch (err) {
      toast('Failed to add question', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteQuestion = async (q) => {
    if (!window.confirm('Delete this question?')) return;
    try {
      await hrDeleteQuestion(q.questionID);
      toast('Question deleted');
      await load();
    } catch { toast('Delete failed', 'error'); }
  };

  return (
    <div style={{ maxWidth: 1280, margin: '0 auto', padding: '40px 32px 80px' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 28 }}>
        <div>
          <h2 style={{ fontSize: 22, fontWeight: 700, marginBottom: 4 }}>Feedback Forms</h2>
          <p style={{ fontSize: 13.5, color: 'var(--gray-500)' }}>Manage employee feedback questions</p>
        </div>
        <Btn onClick={() => { setFormData({ title: '', description: '' }); setShowCreate(true); }}>
          New Form
        </Btn>
      </div>

      {loading ? (
        <div style={{ textAlign: 'center', padding: 80 }}><Spinner /></div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: '340px 1fr', gap: 24, alignItems: 'start' }}>

          {/* Sidebar List */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {forms.map(form => (
              <div key={form.formID}
                onClick={() => handleSelectForm(form)}
                style={{
                  background: 'var(--white)', borderRadius: 20, padding: '20px 22px',
                  border: `2px solid ${selectedForm?.formID === form.formID ? 'var(--red)' : '#EAECF0'}`,
                  cursor: 'pointer', transition: 'all .2s',
                }}>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 8 }}>{form.title}</div>
                <div style={{ display: 'flex', gap: 6 }}>
                  <Badge label={form.isActive ? 'Active' : 'Inactive'} color={form.isActive ? 'green' : 'gray'} />
                  <Badge label={`${form.questions?.length || 0} Qs`} color="accent" />
                </div>
                <div style={{ display: 'flex', gap: 6, marginTop: 12 }}>
                  <Btn size="sm" variant="ghost" style={{ flex: 1 }} onClick={(e) => { e.stopPropagation(); handleToggleActive(form); }}>
                    {form.isActive ? 'Deactivate' : 'Activate'}
                  </Btn>
                  <Btn size="sm" variant="danger" onClick={(e) => { e.stopPropagation(); handleDelete(form); }}>Delete</Btn>
                </div>
              </div>
            ))}
          </div>

          {/* Question Details Area */}
          {selectedForm ? (
            <div style={{ background: 'var(--white)', borderRadius: 24, border: '1px solid #EAECF0', overflow: 'hidden' }}>
              <div style={{ padding: '24px 28px', borderBottom: '1px solid #F3F4F6', display: 'flex', justifyContent: 'space-between' }}>
                <div>
                  <h3 style={{ fontSize: 18, fontWeight: 700 }}>{selectedForm.title}</h3>
                  <p style={{ fontSize: 13, color: 'var(--gray-500)' }}>{selectedForm.description}</p>
                </div>
                <Btn size="sm" onClick={() => setShowAddQ(true)}>Add Question</Btn>
              </div>
              <div style={{ padding: '24px 28px' }}>
                {!selectedForm.questions || selectedForm.questions.length === 0 ? (
                  <p style={{ textAlign: 'center', color: 'var(--gray-400)', fontSize: 14 }}>No questions yet.</p>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                    {selectedForm.questions.map((q, i) => (
                      <div key={q.questionID} style={{ background: 'var(--gray-50)', padding: 16, borderRadius: 16, display: 'flex', justifyContent: 'space-between' }}>
                        <div>
                          <div style={{ fontSize: 10, fontWeight: 800, color: 'var(--red)', textTransform: 'uppercase' }}>{FIELD_LABELS[q.fieldType]}</div>
                          <div style={{ fontWeight: 600 }}>{i + 1}. {q.questionText}</div>
                        </div>
                        <Btn size="sm" variant="danger" onClick={() => handleDeleteQuestion(q)}>Delete</Btn>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div style={{ border: '2px dashed #EAECF0', padding: 60, borderRadius: 24, textAlign: 'center', color: '#98A2B3' }}>
              Select a form to view questions
            </div>
          )}
        </div>
      )}

      {/* Modals (Keep your existing Modal code for Create, Edit, and AddQuestion here) */}
      {/* ... */}
    </div>
  );
}
